// src/models/summary.ts
export interface Summary {
  totalTasks: number;
  byStatus: Record<string, number>;
  byPriority: Record<string, number>;
  tagsSummary: Record<string, number>;
  keyMetrics: { completedRatio: number };
  freeTextOverview: string;
}

// src/summarizer/gate.ts
import { Task } from '../models/task';
import { loadAllTasks } from '../storage/json';

export async function generateSummary(): Promise<Summary> {
  const tasks = await loadAllTasks();
  const byStatus = tasks.reduce((acc, t) => ({ ...acc, [t.status]: (acc[t.status] || 0) + 1 }), {});
  const byPriority = tasks.reduce((acc, t) => ({ ...acc, [t.priority]: (acc[t.priority] || 0) + 1 }), {});
  const tagsSummary = tasks.flatMap(t => t.tags).reduce((acc, tag) => ({ ...acc, [tag]: (acc[tag] || 0) + 1 }), {});
  const completedRatio = (byStatus.completed || 0) / tasks.length || 0;
  const freeTextOverview = tasks.map(t => t.objective).join(' ').split(' ').slice(0, 50).join(' ') + '...'; // Simple truncation
  return { totalTasks: tasks.length, byStatus, byPriority, tagsSummary, keyMetrics: { completedRatio }, freeTextOverview };
}

